UNITS.append(dict(id='u3', title='Molecular Geometry & Bonding', weeks='Weeks 7–9',
 summary='Why atoms bond, how to draw molecules, what shapes they take, and the forces between molecules that decide whether something is a gas, liquid or solid.',
 objectives=['Classify bonds as ionic, polar covalent or nonpolar covalent using electronegativity.',
  'Draw Lewis structures and check them with formal charge.',
  'Predict electron-pair and molecular geometry with VSEPR theory.',
  'Decide whether a molecule is polar from its bonds and shape.',
  'Rank substances by boiling point using intermolecular forces.'],
 concepts=['Ionic bonds form when electrons transfer between atoms with very different electronegativities (for example Na and Cl). Covalent bonds share electron pairs.',
  'Electronegativity is an atom’s pull on shared electrons. Unequal sharing makes a polar bond with partial charges δ+ and δ−.',
  'Lewis structures show valence electrons as bonds and lone pairs. Most main-group atoms end with eight electrons around them (the octet rule); hydrogen ends with two.',
  'Formal charge helps choose the best Lewis structure: the best one has formal charges as close to zero as possible.',
  'VSEPR: electron groups (bonds and lone pairs) around a central atom spread out as far as possible. 2 groups: linear, 180°. 3: trigonal planar, 120°. 4: tetrahedral, 109.5°. 5: trigonal bipyramidal. 6: octahedral.',
  'Lone pairs take up more room than bonds, so they squeeze bond angles: water is bent at about 104.5°, ammonia is trigonal pyramidal at about 107°.',
  'A molecule is polar if its bond dipoles do not cancel. CO₂ has polar bonds but is linear, so it is nonpolar overall; H₂O is bent, so it is polar.',
  'Intermolecular forces, weakest to strongest for similar sizes: London dispersion (all molecules, larger with more electrons), dipole–dipole (polar molecules), hydrogen bonding (H on N, O or F). Stronger forces mean higher boiling points.'],
 eqs=[(r'\text{FC}=V-N-\frac{B}{2}', 'Formal charge: V = valence electrons, N = nonbonding electrons, B = bonding electrons'),
  (r'\Delta\chi=|\chi_A-\chi_B|', 'Electronegativity difference; larger means a more polar bond')],
 worked=[
  dict(q='Draw the Lewis structure of CO₂ and predict its shape and polarity.',
   steps=['Count valence electrons: C has 4, each O has 6: 4 + 2 × 6 = 16.',
    'Put C in the center and connect each O with a double bond: O=C=O uses 8 electrons.',
    'Place the remaining 8 as two lone pairs on each O. Every atom now has an octet.',
    'Formal charges: C = 4 − 0 − 8/2 = 0; each O = 6 − 4 − 4/2 = 0. A good structure.',
    'Two electron groups on C and no lone pairs: linear, 180°. The two C=O dipoles point in opposite directions and cancel.'],
   a='O=C=O, linear and nonpolar overall, even though each bond is polar.'),
  dict(q='Predict the shape, bond angle and polarity of water.',
   steps=['Valence electrons: 2 × 1 + 6 = 8.', 'Two O–H bonds use 4 electrons; the other 4 are two lone pairs on O.',
    'Four electron groups: tetrahedral electron geometry. With two lone pairs, the molecular shape is bent.',
    'Lone pairs push the bonds closer: angle about 104.5°, less than 109.5°.',
    'The bond dipoles do not cancel in a bent shape, so water is polar and can hydrogen bond.'],
   a='Bent, about 104.5°, polar.'),
  dict(q='Which has the higher boiling point: methane (CH₄) or octane (C₈H₁₈)? Why?',
   steps=['Both are nonpolar hydrocarbons, so the main force is London dispersion.', 'Octane has many more electrons and a longer shape, so its dispersion forces are much stronger.'],
   a='Octane. That is why octane is a liquid at room temperature while methane is a gas.')],
 practice=[
  ('Predict the shape and bond angle of NH₃.', 'Four electron groups with one lone pair: trigonal pyramidal, about 107°.'),
  ('Predict the shape of CH₄ and say whether it is polar.', 'Tetrahedral, 109.5°. The four C–H dipoles cancel, so it is nonpolar.'),
  ('Is BF₃ polar?', 'No. It is trigonal planar with three identical B–F bonds whose dipoles cancel.'),
  ('What is the shape of SF₆?', 'Octahedral (six bonding groups, no lone pairs on S), 90° bond angles.'),
  ('Find the formal charge on N in the ammonium ion, NH₄⁺.', 'FC = 5 − 0 − 8/2 = +1.'),
  ('Why does H₂O boil at 100 °C while the heavier H₂S boils far lower?', 'Water molecules hydrogen bond to each other; H₂S cannot hydrogen bond as strongly, so less energy is needed to separate its molecules.'),
  ('Is SO₂ polar or nonpolar?', 'Polar. Sulfur has a lone pair, so SO₂ is bent and its bond dipoles do not cancel.')],
 misc=[('A molecule with polar bonds must be polar.', 'Shape matters. CO₂ and CCl₄ have polar bonds but symmetric shapes, so they are nonpolar.'),
  ('Boiling breaks the bonds inside molecules.', 'Boiling water separates H₂O molecules from each other. The O–H bonds inside each molecule stay intact.'),
  ('Lone pairs do not affect shape because you cannot see them in the formula.', 'Lone pairs repel more strongly than bonds and bend the shape, as in H₂O and NH₃.'),
  ('Hydrogen bonds are bonds to hydrogen atoms in any molecule.', 'They need H bonded to N, O or F, attracted to a lone pair on another N, O or F.')],
 quiz=[dict(q='What is the molecular shape of a central atom with 3 bonds and 1 lone pair?', opts=['Trigonal planar', 'Trigonal pyramidal', 'Bent', 'Tetrahedral'], ok=1, why='Four electron groups, one a lone pair: trigonal pyramidal, like NH₃.'),
  dict(q='Which molecule is nonpolar?', opts=['H₂O', 'NH₃', 'CO₂', 'SO₂'], ok=2, why='Linear CO₂ has opposite bond dipoles that cancel.'),
  dict(q='Which intermolecular force is present in all molecules?', opts=['Hydrogen bonding', 'Dipole–dipole', 'London dispersion', 'Ion–dipole'], ok=2, why='Every molecule has electrons that can form temporary dipoles.'),
  dict(q='What is the ideal bond angle in a tetrahedral molecule?', opts=['90°', '109.5°', '120°', '180°'], ok=1, why='Four groups spread out in 3D at 109.5°.'),
  dict(q='How many valence electrons are in the Lewis structure of CO₂?', opts=['12', '14', '16', '22'], ok=2, why='4 from C plus 6 from each O.')],
 cards=[('Electronegativity', 'How strongly an atom pulls shared electrons toward itself.'), ('Octet rule', 'Main-group atoms tend to end with eight valence electrons.'),
  ('Formal charge', 'FC = V − N − B/2; best structures keep it near zero.'), ('VSEPR, 4 groups', 'Tetrahedral, 109.5°.'),
  ('Water’s shape', 'Bent, about 104.5°.'), ('Hydrogen bond', 'Attraction between H on N/O/F and a lone pair on another N/O/F.'),
  ('London dispersion', 'Weak attraction from temporary dipoles; grows with more electrons.'), ('Polar molecule', 'Bond dipoles do not cancel because of its shape.')],
 planet=dict(text=['Molecular shape explains the greenhouse effect. Molecules such as CO₂, CH₄ and H₂O can bend or stretch in ways that change their dipole, so they absorb infrared heat radiating from Earth. N₂ and O₂, which make up most of the air, cannot.',
   'Hydrogen bonding makes ice less dense than liquid water, so ice floats. Lakes freeze from the top down, and fish and other life survive the winter in the water below.',
   'Intermolecular forces also guide cleanups: oil is nonpolar and does not mix with water, which is why spills spread as surface slicks.'],
  site=[('GOSAT-GW: greenhouse gases from space', 'GOSAT-GW.html'), ('Lakes hub', 'Lakes.html')], src=[('U.S. EPA: Overview of Greenhouse Gases', 'https://www.epa.gov/ghgemissions/overview-greenhouse-gases')]),
 res=[('OpenStax Chemistry 2e, Chapter 7: Chemical Bonding and Molecular Geometry', OS + '7-introduction', 'Lewis structures, formal charge and VSEPR.'),
  ('OpenStax Chemistry 2e, 7.6 Molecular Structure and Polarity', OS + '7-6-molecular-structure-and-polarity', 'Shapes and dipoles with worked examples.'),
  ('OpenStax Chemistry 2e, 10.1 Intermolecular Forces', OS + '10-1-intermolecular-forces', 'Dispersion, dipole–dipole and hydrogen bonding.'),
  ('PhET: Molecule Shapes', 'https://phet.colorado.edu/en/simulations/molecule-shapes', 'Build molecules in 3D and watch lone pairs change the shape.'),
  ('PhET: Molecule Polarity', 'https://phet.colorado.edu/en/simulations/molecule-polarity', 'Change electronegativity and see bond and molecular dipoles.')]))
UNITS.append(dict(id='u4', title='States of Matter: Gases & Solutions', weeks='Weeks 10–12',
 summary='How gases respond to pressure and temperature, how gas mixtures work, and how substances (including oxygen and CO₂) dissolve in water.',
 objectives=['Use Boyle’s, Charles’s and the combined gas law, always in kelvin.',
  'Solve problems with the ideal gas law, PV = nRT, including molar mass from density.',
  'Use Dalton’s law of partial pressures.',
  'Explain gas behavior with kinetic-molecular theory.',
  'Describe solubility, and use Henry’s law for gases dissolving in liquids.'],
 concepts=['Gas laws need absolute temperature: T(K) = T(°C) + 273.15.',
  'At constant temperature, pressure and volume are inversely related (Boyle). At constant pressure, volume is proportional to kelvin temperature (Charles).',
  'The ideal gas law, PV = nRT, ties pressure, volume, moles and temperature together. At 0 °C and 1 atm, one mole of an ideal gas takes up 22.4 L.',
  'In a gas mixture, each gas exerts its own partial pressure, and they add up to the total (Dalton’s law). Dry air is about 20.95% oxygen by volume.',
  'Kinetic-molecular theory: gas particles move fast and randomly, collide elastically, and their average kinetic energy is proportional to kelvin temperature.',
  'A solution is a uniform mixture. “Like dissolves like”: polar solvents such as water dissolve polar and ionic substances.',
  'The amount of a gas that dissolves in a liquid rises with that gas’s partial pressure (Henry’s law) and usually falls as the water warms.'],
 eqs=[(r'PV=nRT', 'Ideal gas law'),
  (r'R=0.08206\ \frac{\text{L·atm}}{\text{mol·K}}=8.314\ \frac{\text{J}}{\text{mol·K}}', 'Gas constant'),
  (r'\frac{P_1V_1}{T_1}=\frac{P_2V_2}{T_2}', 'Combined gas law (fixed amount of gas)'),
  (r'P_\text{total}=P_A+P_B+\dots,\qquad P_A=x_A\,P_\text{total}', 'Dalton’s law; x is the mole fraction'),
  (r'M=\frac{dRT}{P}', 'Molar mass from gas density d'),
  (r'C_g=k_H\,P_g', 'Henry’s law: dissolved gas concentration')],
 worked=[
  dict(q='What volume does 1.00 mol of an ideal gas occupy at 25.0 °C and 1.00 atm?',
   steps=['Convert temperature: 25.0 + 273.15 = 298.2 K.', 'V = nRT/P = 1.00 mol × 0.08206 L·atm/(mol·K) × 298.2 K ÷ 1.00 atm.', 'V = 24.5 L.'],
   a='24.5 L, a bit more than the 22.4 L at 0 °C because warmer gas expands.'),
  dict(q='A weather balloon holds 2.00 L of helium at 1.00 atm and 300 K. It rises to where the pressure is 0.500 atm and the temperature is 250 K. What is its new volume?',
   steps=['Combined gas law solved for V₂: V₂ = V₁ × (P₁/P₂) × (T₂/T₁).', 'V₂ = 2.00 L × (1.00/0.500) × (250/300).', 'V₂ = 2.00 L × 2 × 0.8333 = 3.33 L.'],
   a='3.33 L. Lower pressure lets it expand more than the cold shrinks it.'),
  dict(q='Estimate how much oxygen dissolves in water at 25 °C open to air at 1.00 atm. Henry’s constant for O₂ is about 1.3 × 10⁻³ mol/(L·atm).',
   steps=['Partial pressure of O₂: 0.2095 × 1.00 atm = 0.21 atm.', 'C = k_H × P = 1.3 × 10⁻³ mol/(L·atm) × 0.21 atm = 2.7 × 10⁻⁴ mol/L.', 'Convert to mass: 2.7 × 10⁻⁴ mol/L × 32.00 g/mol = 8.7 × 10⁻³ g/L = 8.7 mg/L.'],
   a='About 9 mg of oxygen per liter: a small amount, and all that fish and other aquatic life have to breathe.')],
 practice=[
  ('Convert 25 °C and −40 °C to kelvin.', '298 K and 233 K (add 273.15).'),
  ('How many moles of gas fill 10.0 L at 0 °C (273.15 K) and 1.00 atm?', 'n = PV/RT = (1.00 × 10.0) ÷ (0.08206 × 273.15) = 0.446 mol.'),
  ('At constant temperature, what happens to a gas volume if the pressure doubles?', 'It halves (Boyle’s law).'),
  ('A gas has a density of 1.25 g/L at 0 °C and 1.00 atm. Find its molar mass.', 'M = dRT/P = 1.25 × 0.08206 × 273.15 ÷ 1.00 = 28.0 g/mol (consistent with N₂).'),
  ('A tank holds 2.0 mol N₂ and 0.50 mol O₂ at 5.0 atm total. What is the O₂ partial pressure?', 'x(O₂) = 0.50 ÷ 2.5 = 0.20; P(O₂) = 0.20 × 5.0 atm = 1.0 atm.'),
  ('Why does a can of soda go flat faster when warm?', 'Gas solubility falls as temperature rises, so dissolved CO₂ escapes more quickly.')],
 misc=[('You can use °C in gas laws.', 'Always use kelvin. At 0 °C the volume is not zero; at 0 K it would be.'),
  ('22.4 L/mol is true for any gas at any conditions.', 'It applies only to an ideal gas at 0 °C and 1 atm. At 25 °C it is about 24.5 L.'),
  ('Heavier gas molecules move faster at the same temperature.', 'At the same temperature all gases have the same average kinetic energy, so heavier molecules move slower.'),
  ('Gases dissolve better in warm water, like sugar does.', 'Most gases are less soluble in warmer water.')],
 quiz=[dict(q='Which temperature scale must gas-law calculations use?', opts=['Celsius', 'Fahrenheit', 'Kelvin', 'Any of these'], ok=2, why='Gas laws are proportional to absolute temperature.'),
  dict(q='At constant pressure, a gas is heated from 200 K to 400 K. Its volume…', opts=['halves', 'doubles', 'stays the same', 'quadruples'], ok=1, why='Charles’s law: V is proportional to T in kelvin.'),
  dict(q='Air at 1.00 atm is about 21% O₂. The partial pressure of O₂ is about…', opts=['0.21 atm', '0.79 atm', '1.00 atm', '21 atm'], ok=0, why='P(O₂) = 0.21 × 1.00 atm.'),
  dict(q='What happens to dissolved oxygen as a lake warms?', opts=['It rises', 'It falls', 'It does not change', 'It turns into CO₂'], ok=1, why='Gas solubility in water usually decreases with temperature.'),
  dict(q='What is R in L·atm/(mol·K)?', opts=['8.314', '0.08206', '22.4', '6.022 × 10²³'], ok=1, why='8.314 is the value in J/(mol·K).')],
 cards=[('Ideal gas law', 'PV = nRT.'), ('R', '0.08206 L·atm/(mol·K) or 8.314 J/(mol·K).'), ('Boyle’s law', 'P₁V₁ = P₂V₂ at constant n and T.'),
  ('Charles’s law', 'V₁/T₁ = V₂/T₂ at constant n and P.'), ('Dalton’s law', 'Total pressure is the sum of the partial pressures.'),
  ('Henry’s law', 'Dissolved gas concentration = k_H × partial pressure.'), ('Kelvin', 'T(K) = T(°C) + 273.15.'), ('Molar volume', '22.4 L/mol for an ideal gas at 0 °C and 1 atm.')],
 planet=dict(text=['Dissolved gases decide what can live in water. Because warm water holds less oxygen, warming lakes and rivers can stress fish, and water-quality teams measure dissolved oxygen to protect them.',
   'Henry’s law also explains ocean acidification. As CO₂ in the air rises, more dissolves in seawater and forms carbonic acid. NOAA reports that the ocean absorbs about 30% of the CO₂ released into the atmosphere and that surface ocean pH has fallen by about 0.1 since the industrial revolution, roughly a 30% increase in acidity.',
   'That matters to people as well as reefs: NOAA notes that oysters, corals and other shell builders struggle in more acidic water, and many fisheries and coastal jobs depend on them.'],
  site=[('Oceans hub', 'Oceans.html'), ('PACE: ocean color and plankton', 'PACE.html')], src=[('NOAA: Ocean acidification (education)', 'https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification')]),
 res=[('OpenStax Chemistry 2e, Chapter 9: Gases', OS + '9-introduction', 'Gas laws, mixtures and kinetic-molecular theory.'),
  ('OpenStax Chemistry 2e, Chapter 11: Solutions and Colloids', OS + '11-introduction', 'Solubility and Henry’s law.'),
  ('PhET: Gas Properties', 'https://phet.colorado.edu/en/simulations/gas-properties', 'Pump gas, heat it and watch pressure change.'),
  ('NOAA: Ocean acidification resources', 'https://www.noaa.gov/education/resource-collections/ocean-coasts/ocean-acidification', 'Lessons, data and labs on CO₂ in seawater.')]))
UNITS.append(dict(id='u5', title='Thermodynamics', weeks='Weeks 13–14',
 summary='Chemical energy: heat, enthalpy, why some reactions release energy, and a first look at entropy and Gibbs free energy.',
 objectives=['Use q = mcΔT and calorimetry to find heat flow and specific heat.',
  'Classify processes as exothermic or endothermic and give the sign of ΔH.',
  'Use Hess’s law and standard enthalpies of formation to find ΔH of a reaction.',
  'State the first law of thermodynamics with the chemistry sign convention.',
  'Use ΔG = ΔH − TΔS to judge whether a process is spontaneous.'],
 concepts=['Energy is conserved (the first law): ΔU = q + w. In chemistry, q is heat added to the system and w is work done on the system.',
  'Exothermic reactions release heat to the surroundings (ΔH < 0); endothermic reactions absorb heat (ΔH > 0).',
  'Specific heat c is the heat needed to warm 1 g by 1 °C. Water’s is high, 4.184 J/(g·°C), which is why oceans and lakes warm and cool slowly.',
  'Enthalpy is a state function, so ΔH depends only on start and end. That is why Hess’s law works: you can add reactions and add their ΔH values.',
  'Standard enthalpy of formation (ΔH°f) is the enthalpy change to make 1 mol of a compound from its elements in their standard states. For an element in its standard state, ΔH°f = 0.',
  'Entropy (S) measures how spread out energy and matter are. The Gibbs free energy change, ΔG = ΔH − TΔS, is negative for a spontaneous process at constant temperature and pressure.'],
 eqs=[(r'q=mc\Delta T', 'Heat for a temperature change'),
  (r'q_\text{lost}=-q_\text{gained}', 'Calorimetry: heat lost by the hot object equals heat gained by the cold one'),
  (r'\Delta U=q+w,\qquad w=-P\Delta V', 'First law (chemistry sign convention)'),
  (r'\Delta H^\circ_\text{rxn}=\sum n\,\Delta H^\circ_f(\text{products})-\sum n\,\Delta H^\circ_f(\text{reactants})', 'Reaction enthalpy from formation enthalpies'),
  (r'\Delta G=\Delta H-T\Delta S', 'Gibbs free energy')],
 worked=[
  dict(q='How much heat does it take to warm 250.0 g of water from 20.0 °C to 100.0 °C?',
   steps=['ΔT = 100.0 − 20.0 = 80.0 °C.', 'q = mcΔT = 250.0 g × 4.184 J/(g·°C) × 80.0 °C = 83,680 J.', 'In kilojoules: 83.7 kJ.'],
   a='83.7 kJ.'),
  dict(q='Find ΔH° for burning methane, CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l), using ΔH°f values: CH₄(g) −74.6, CO₂(g) −393.5, H₂O(l) −285.8 kJ/mol; O₂(g) 0.',
   steps=['Products: −393.5 + 2 × (−285.8) = −965.1 kJ.', 'Reactants: −74.6 + 2 × 0 = −74.6 kJ.', 'ΔH° = −965.1 − (−74.6) = −890.5 kJ.'],
   a='About −890 kJ per mole of methane: strongly exothermic.'),
  dict(q='Compare the heat released per gram by methane and by hydrogen. For H₂(g) + ½ O₂(g) → H₂O(l), ΔH° = −285.8 kJ.',
   steps=['Methane: 890.5 kJ ÷ 16.04 g = 55.5 kJ/g.', 'Hydrogen: 285.8 kJ ÷ 2.016 g = 141.8 kJ/g.', 'Products: methane makes CO₂; hydrogen makes only water.'],
   a='Hydrogen releases about 2.6 times more heat per gram, and burning it makes no CO₂. Whether hydrogen is clean overall depends on how it was produced.'),
  dict(q='A reaction has ΔH = +40.0 kJ and ΔS = +120 J/K. Is it spontaneous at 298 K? Above what temperature does it become spontaneous?',
   steps=['Use the same units: ΔS = 0.120 kJ/K.', 'At 298 K: ΔG = 40.0 − 298 × 0.120 = 40.0 − 35.8 = +4.2 kJ. Positive, so not spontaneous.',
    'Set ΔG = 0: T = ΔH/ΔS = 40.0 ÷ 0.120 = 333 K.'],
   a='Not spontaneous at 298 K; spontaneous above about 333 K (60 °C).')],
 practice=[
  ('How much heat raises 1.00 kg of water by 10.0 °C?', 'q = 1000 g × 4.184 × 10.0 = 41,840 J = 41.8 kJ.'),
  ('Is melting ice endothermic or exothermic? What is the sign of q for the ice?', 'Endothermic; q is positive because the ice absorbs heat.'),
  ('A 50.0 g metal at 100.0 °C is dropped into 100.0 g of water at 20.0 °C. Both end at 22.0 °C. Find the metal’s specific heat.', 'Heat gained by water = 100.0 × 4.184 × 2.0 = 836.8 J. Metal: 836.8 = 50.0 × c × 78.0, so c = 0.215 J/(g·°C).'),
  ('Use Hess’s law: C(s) + O₂ → CO₂, ΔH = −393.5 kJ; CO + ½ O₂ → CO₂, ΔH = −283.0 kJ. Find ΔH for C(s) + ½ O₂ → CO.', 'Reverse the second and add: −393.5 + 283.0 = −110.5 kJ.'),
  ('What is ΔH°f for O₂(g)?', 'Zero: it is an element in its standard state.'),
  ('A process has ΔH < 0 and ΔS > 0. When is it spontaneous?', 'At every temperature, because ΔG = ΔH − TΔS is always negative.')],
 misc=[('Heat and temperature are the same thing.', 'Temperature measures average particle energy; heat is energy transferred. A bathtub of warm water holds more heat than a cup of boiling water.'),
  ('Exothermic reactions always happen on their own.', 'Spontaneity depends on ΔG, which includes entropy. Some exothermic reactions are not spontaneous at high temperatures.'),
  ('A spontaneous reaction is a fast one.', 'Spontaneous tells you the direction, not the speed. Diamond turning into graphite is spontaneous but far too slow to notice.'),
  ('Breaking bonds releases energy.', 'Breaking bonds always takes energy. Energy is released when new, stronger bonds form.')],
 quiz=[dict(q='The sign of ΔH for an exothermic reaction is…', opts=['positive', 'negative', 'zero', 'it depends on temperature'], ok=1, why='The system loses heat to the surroundings.'),
  dict(q='Water’s specific heat is…', opts=['1.00 J/(g·°C)', '4.184 J/(g·°C)', '8.314 J/(g·°C)', '0.449 J/(g·°C)'], ok=1, why='4.184 J warms 1 g of water by 1 °C.'),
  dict(q='Hess’s law works because enthalpy is…', opts=['always negative', 'a state function', 'equal to entropy', 'measured in kelvin'], ok=1, why='ΔH depends only on the start and end states.'),
  dict(q='A reaction is spontaneous when…', opts=['ΔG < 0', 'ΔG > 0', 'ΔH > 0', 'ΔS = 0'], ok=0, why='Negative Gibbs energy change means the process can proceed on its own.'),
  dict(q='Per gram, which fuel releases more heat when burned to liquid water?', opts=['Methane', 'Hydrogen', 'They are equal', 'Neither releases heat'], ok=1, why='About 142 kJ/g for hydrogen vs. 55.5 kJ/g for methane.')],
 cards=[('q = mcΔT', 'Heat = mass × specific heat × temperature change.'), ('Exothermic', 'Releases heat; ΔH < 0.'), ('Endothermic', 'Absorbs heat; ΔH > 0.'),
  ('Hess’s law', 'ΔH of a sum of reactions is the sum of their ΔH values.'), ('ΔH°f of an element', 'Zero in its standard state.'),
  ('First law', 'ΔU = q + w; energy is conserved.'), ('Gibbs energy', 'ΔG = ΔH − TΔS; negative means spontaneous.'), ('Specific heat of water', '4.184 J/(g·°C).')],
 planet=dict(text=['Thermochemistry is the accounting behind clean energy. Comparing kilojoules per gram and CO₂ per kilojoule, as in the worked examples, shows why hydrogen made with clean power can cut emissions.',
   'The U.S. Department of Energy notes that hydrogen used in a fuel cell produces only water, and that hydrogen can be made from many sources, including solar and wind power.',
   'Water’s high specific heat lets oceans store huge amounts of heat, which steadies coastal climates for people and wildlife.'],
  site=[('Sentinel-6B: tracking sea level', 'Sentinel-6B.html'), ('Earth Observation hub', 'Earth_Observation.html')], src=[('U.S. DOE: Hydrogen fuel basics', 'https://www.energy.gov/eere/fuelcells/hydrogen-fuel-basics')]),
 res=[('OpenStax Chemistry 2e, Chapter 5: Thermochemistry', OS + '5-introduction', 'Calorimetry, enthalpy and Hess’s law.'),
  ('OpenStax Chemistry 2e, Chapter 16: Thermodynamics', OS + '16-introduction', 'Entropy and Gibbs free energy.'),
  ('PhET: Energy Forms and Changes', 'https://phet.colorado.edu/en/simulations/energy-forms-and-changes', 'Watch heat flow between objects.'),
  ('MIT OpenCourseWare 3.091 Introduction to Solid-State Chemistry', 'https://ocw.mit.edu/courses/3-091-introduction-to-solid-state-chemistry-fall-2018/', 'Free lectures that also cover bonding and energy.')]))
LAB_INTRO = ['The lab is the hands-on part of the course, a 1-credit component in a typical college schedule. Here it is free and for practice only.',
 'You put lecture ideas into practice with digital sensors, meters and precision glassware. Do the wet-lab versions only in a supervised school or college lab; each exercise also has a safe home or virtual version.']
LAB_GEAR = ['Digital balance (to 0.001 g)', 'pH meter or probe', 'Spectrophotometer or colorimeter with cuvettes', 'Burette, volumetric pipets and flasks', 'Crucible, lid, clay triangle and burner', 'Safety goggles, gloves and lab coat']
