 table=(['Trial', 'Initial reading (mL)', 'Final reading (mL)', 'NaOH used (mL)'], [['1 (rough)', '0.50', '23.10', '22.60'], ['2', '0.20', '22.65', '22.45'], ['3', '1.05', '23.52', '22.47']]),
 note='Sample data for practice only. Average the trials that agree (2 and 3).',
